(* [comment removed for export] *)
Section ERUNS.
Variable O : Type.
Variable sel : O -> E -> option A.
Variable upd : O -> E -> A -> O.

Fixpoint eruns (R : Type) (o : O) (t : stree R) {struct t} : stree (O * R) :=
  match t with
  | SRet r => SRet (o, r)
  | SVis e k =>
      match sel o e with
      | Some a => eruns (upd o e a) (k a)
      | None => SVis e (fun a => eruns (upd o e a) (k a))
      end
  end.

